        // \u67e5\u627e\u7528\u6237\u5e76\u83b7\u53d6\u5176\u5173\u8054\u7684\u89d2\u8272\u548c\u6743\u9650\n            const user = await this.userService.findOne({ where: { id: decoded.id }, relations: ['roles', 'roles.accesses'] });\n            // \u5982\u679c\u627e\u5230\u7528\u6237\n            if (user) {\n                // \u5220\u9664\u7528\u6237\u5bc6\u7801\uff0c\u9632\u6b62\u66b4\u9732\u654f\u611f\u4fe1\u606f\n                delete user.password;\n                // \u5c06\u7528\u6237\u4fe1\u606f\u9644\u52a0\u5230\u8bf7\u6c42\u5bf9\u8c61\n                request.user = user;\n                // \u8fd4\u56de true\uff0c\u8868\u793a\u901a\u8fc7\u8eab\u4efd\u9a8c\u8bc1\n                return true;\n            } else {\n                // \u5982\u679c\u7528\u6237\u4e0d\u5b58\u5728\uff0c\u629b\u51fa\u672a\u6388\u6743\u5f02\u5e38\n                throw new UnauthorizedException('User not found');\n            }\n        } catch (error) {\n            // \u6355\u83b7\u4ee4\u724c\u9a8c\u8bc1\u9519\u8bef\u5e76\u629b\u51fa\u672a\u6388\u6743\u5f02\u5e38\n            throw new UnauthorizedException('Invalid or expired token');\n        }\n    }\n    // \u4ece\u8bf7\u6c42\u5934\u4e2d\u63d0\u53d6\u4ee4\u724c\u7684\u79c1\u6709\u65b9\u6cd5\n    private extractTokenFromHeader(request: Request): string | undefined {\n        // \u4ece\u8bf7\u6c42\u5934\u4e2d\u83b7\u53d6\u6388\u6743\u4fe1\u606f\uff0c\u5e76\u6309\u7167\u7a7a\u683c\u5206\u9694\u4e3a\u7c7b\u578b\u548c\u4ee4\u724c\n        const [type, token] = request.headers.authorization?.split(' ') ?? [];\n        // \u5982\u679c\u7c7b\u578b\u4e3a 'Bearer'\uff0c\u5219\u8fd4\u56de\u4ee4\u724c\uff0c\u5426\u5219\u8fd4\u56de undefined\n        return type === 'Bearer' ? token : undefined;\n    }\n}\n")),(0,r.kt)("h3",{id:"23-authcontrollerts"},"2.3. auth.controller.ts"),(0,r.kt)("p",null,"src/api/controllers/auth.controller.ts"),(0,r.kt)("pre",null,(0,r.kt)("code",{parentName:"pre",className:"language-diff"},"import { Contr